3	import com.example.starter.domain.Point;
4	import org.springframework.dao.EmptyResultDataAccessException;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.stereotype.Repository;
7	
8	import java.util.List;
9	
10	/**
11	 * 航线与航点数据访问。
12	 */
13	@Repository
14	public class RouteRepository {
15	
16	    private final JdbcTemplate jdbc;
17	
18	    public RouteRepository(JdbcTemplate jdbc) {
19	        this.jdbc = jdbc;
20	    }
21	
22	    /** 按 routeId 查询航线（含当前版本点列），不存在返回 null。 */
23	    public RoutePo findRoute(String routeId) {
24	        Integer version;
25	        try {
