public static EnergyCheckResult evaluate(EnergyProfile profile) {
    long cumulative = 0;
    List<PointEnergy> points = new ArrayList<>();
    int n = profile.alternateEnergies().size();
    for (int i = 0; i < n; i++) {
        if (i > 0) cumulative = Math.addExact(cumulative, profile.segmentEnergies().get(i-1));
        long required = Math.addExact(Math.addExact(cumulative, profile.alternateEnergies().get(i)), profile.reserveEnergy());
        boolean ok = required <= profile.departureEnergy();
        points.add(new PointEnergy(i, cumulative, alt, required, ok));
    }
    // find first insufficient
    for (PointEnergy p : points) if (!p.sufficient()) return new EnergyCheckResult(points, p.seq(), p.requiredEnergy() - profile.departureEnergy());
    return new EnergyCheckResult(points, null, null);
}
