51	                }
52	            } else {
53	                double r = q[i] / p[i];
54	                if (p[i] < 0L) {
55	                    if (r > t1) {
56	                        return false;
57	                    }
58	                    if (r > t0) {
59	                        t0 = r;
60	                    }
61	                } else {
62	                    if (r < t0) {
